"""Compile actual firmware settings generated by the TUI, without ESP hardware."""
from pathlib import Path
import shutil
import subprocess
import tempfile
import unittest

from somfy_setup.config import Installation


PROJECT = Path(__file__).resolve().parents[2]
CXX = shutil.which("c++") or shutil.which("g++")


@unittest.skipUnless(CXX, "A host C++ compiler is required")
class FirmwareConfigTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.project = Path(self.temp.name)
        (self.project / "include").mkdir()
        for name in ["somfy_config.h", "shade_settings.h"]:
            shutil.copyfile(PROJECT / "include" / name, self.project / "include" / name)

    def compile(self, body):
        source = self.project / "check.cpp"
        source.write_text('#include "shade_settings.h"\n#include <cassert>\n' + body)
        binary = self.project / "check"
        result = subprocess.run([CXX, "-std=c++17", "-Wall", "-Wextra", "-Werror",
                                 "-I" + str(self.project / "include"),
                                 "-I" + str(PROJECT / "components/shade_ctl/include"),
                                 str(source), "-o", str(binary)], capture_output=True, text=True)
        return result, binary

    def test_legacy_firmware_settings_keep_the_existing_installation(self):
        result, binary = self.compile('''int main() {
            for (unsigned i = 0; i < SHADE_COUNT; i++) {
                auto cfg = somfy_settings::for_shade(i);
                assert(cfg.travel_open_ms == 17900);
                assert(cfg.travel_close_ms == 17100);
                assert(cfg.close_uses_favourite);
                assert(cfg.open_is_hard_limit && !cfg.close_is_hard_limit);
                assert(cfg.stop_lead_ms == 150 && cfg.favourite_delay_ms == 1200);
            }
        }''')
        self.assertEqual(result.returncode, 0, result.stderr)
        subprocess.run([str(binary)], check=True)

    def test_tui_generated_header_drives_each_firmware_shade_independently(self):
        config = Installation.load(self.project)
        config.shades[0].open_ms = 22000
        config.shades[1].close_ms = 31000
        config.shades[1].favourite = False
        config.shades[1].close_limit = True
        config.shades[2].open_limit = False
        config.save(self.project)
        result, binary = self.compile('''int main() {
            auto a = somfy_settings::for_shade(0);
            auto b = somfy_settings::for_shade(1);
            auto c = somfy_settings::for_shade(2);
            assert(a.travel_open_ms == 22000 && a.travel_close_ms == 17100);
            assert(b.travel_open_ms == 17900 && b.travel_close_ms == 31000);
            assert(!b.close_uses_favourite && b.close_is_hard_limit);
            assert(a.close_uses_favourite && c.close_uses_favourite);
            assert(a.open_is_hard_limit && !c.open_is_hard_limit);
        }''')
        self.assertEqual(result.returncode, 0, result.stderr)
        subprocess.run([str(binary)], check=True)

    def test_firmware_rejects_invalid_list_lengths_and_times(self):
        local = self.project / "include/somfy_config.local.h"
        for value in ['{ 12000, 15000 }', '{ 12000, 0, 15000 }']:
            local.write_text(f'#define SHADE_TRAVEL_OPEN_MS_PER_SHADE {value}\n')
            result, _ = self.compile('int main() {}')
            self.assertNotEqual(result.returncode, 0)
